INSERT INTO "tenant_rmribar"."repositories" ("repo_id", "colg_cd", "course_cd", "branch_cd", "batch_cd", "sem_cd", "student_reg_no", "student_name", "title", "description", "repo_link", "tech_stack", "status", "is_placement_eligible", "score", "grade", "submitted_at", "updated_at", "screenshots", "incubation_status", "incubation_notes", "funding_amount", "mentor_assigned", "incubated_at") VALUES (10, '1', '1', '1', '1', '7', '2025107990', 'AAFREEN KHAN', 'AI-Powered Diabetic Retinopathy Diagnostic Engine', 'A deep learning computer vision pipeline utilizing ResNet-50 and EfficientNet-B4 to classify high-resolution fundus images into 5 severity stages of diabetic retinopathy with 96.4% AUC accuracy.', 'https://github.com/aafreen-khan/diabetic-retinopathy-ai', '["Python","PyTorch","FastAPI","Next.js","PostgreSQL","Docker"]'::jsonb, 'Reviewed', TRUE, '94.50', 'A+', '2026-08-20T07:07:32.501Z', '2026-08-23T07:07:32.501Z', '["https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800&auto=format&fit=crop&q=80","https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=800&auto=format&fit=crop&q=80"]'::jsonb, 'Selected', 'Exceptional clinical accuracy. Fast-tracked for SRMS Incubation Center seed grant.', '150000', 'Dr. Rajesh Sharma (Head of AI Research)', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "tenant_rmribar"."repositories" ("repo_id", "colg_cd", "course_cd", "branch_cd", "batch_cd", "sem_cd", "student_reg_no", "student_name", "title", "description", "repo_link", "tech_stack", "status", "is_placement_eligible", "score", "grade", "submitted_at", "updated_at", "screenshots", "incubation_status", "incubation_notes", "funding_amount", "mentor_assigned", "incubated_at") VALUES (11, '1', '1', '1', '1', '7', '2025107666', 'JATIN PRATAP SINGH', 'Autonomous Smart Campus IoT Energy Optimization Grid', 'Distributed IoT sensors and edge computing nodes optimizing HVAC, solar array storage, and smart lighting across multi-tier campus blocks reducing peak energy drain by 28%.', 'https://github.com/jatin-pratap/smart-campus-energy-grid', '["C++","MQTT","ESP32","Node.js","InfluxDB","Grafana","React"]'::jsonb, 'Reviewed', TRUE, '88.00', 'A', '2026-08-20T07:07:32.545Z', '2026-08-23T07:07:32.545Z', '["https://images.unsplash.com/photo-1518770660439-4636190af475?w=800&auto=format&fit=crop&q=80","https://images.unsplash.com/photo-1504384308090-c894fdcc538d?w=800&auto=format&fit=crop&q=80"]'::jsonb, 'Selected', 'Approved for pilot deployment across Engineering Block A & B.', '100000', 'Prof. Ashish Kumar', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "tenant_rmribar"."repositories" ("repo_id", "colg_cd", "course_cd", "branch_cd", "batch_cd", "sem_cd", "student_reg_no", "student_name", "title", "description", "repo_link", "tech_stack", "status", "is_placement_eligible", "score", "grade", "submitted_at", "updated_at", "screenshots", "incubation_status", "incubation_notes", "funding_amount", "mentor_assigned", "incubated_at") VALUES (12, '1', '1', '2', '1', '7', '2025107888', 'PRIYA SHARMA', 'Blockchain-Backed MedERP Electronic Health Records Protocol', 'Zero-Knowledge Proof (ZKP) cryptographic protocol securing patient medical histories, clinical prescriptions, and cross-hospital consent workflows under HIPAA & NDHM compliance.', 'https://github.com/priya-sharma/zk-ehr-blockchain', '["Solidity","Rust","Ethers.js","TypeScript","IPFS","Next.js"]'::jsonb, 'Reviewed', TRUE, '91.00', 'A+', '2026-08-20T07:07:32.556Z', '2026-08-23T07:07:32.556Z', '["https://images.unsplash.com/photo-1526374965328-7f61d4dc18c5?w=800&auto=format&fit=crop&q=80"]'::jsonb, 'Funded', 'Awarded INR 2,00,000 research & development grant by Trust Incubation Board.', '200000', 'Dr. Ankur Rastogi', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "tenant_rmribar"."repositories" ("repo_id", "colg_cd", "course_cd", "branch_cd", "batch_cd", "sem_cd", "student_reg_no", "student_name", "title", "description", "repo_link", "tech_stack", "status", "is_placement_eligible", "score", "grade", "submitted_at", "updated_at", "screenshots", "incubation_status", "incubation_notes", "funding_amount", "mentor_assigned", "incubated_at") VALUES (13, '1', '1', '3', '1', '7', '2025107555', 'ROHAN VERMA', 'FPGA-Accelerated Real-Time Ultrasound Doppler Signal Processor', 'High-throughput hardware acceleration using Xilinx Zynq UltraScale+ FPGA for real-time blood velocity profile synthesis and cardiac vascular strain analysis.', 'https://github.com/rohan-verma/fpga-ultrasound-dsp', '["Verilog","VHDL","Xilinx Vivado","C","Matlab","Python"]'::jsonb, 'Reviewed', TRUE, '85.50', 'A', '2026-08-20T07:07:32.565Z', '2026-08-23T07:07:32.565Z', '["https://images.unsplash.com/photo-1581092160607-ee22621dd758?w=800&auto=format&fit=crop&q=80"]'::jsonb, 'Under Review', 'Under committee technical evaluation for hardware lab fabrication.', '0', 'Prof. S. K. Singh', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "tenant_rmribar"."repositories" ("repo_id", "colg_cd", "course_cd", "branch_cd", "batch_cd", "sem_cd", "student_reg_no", "student_name", "title", "description", "repo_link", "tech_stack", "status", "is_placement_eligible", "score", "grade", "submitted_at", "updated_at", "screenshots", "incubation_status", "incubation_notes", "funding_amount", "mentor_assigned", "incubated_at") VALUES (14, '1', '2', '4', '1', '7', '2025107444', 'ANANYA MISHRA', 'Molecular Docking & In-Silico Drug Repurposing for Oncology Targets', 'Virtual screening and molecular dynamics simulations of 4,000+ FDA-approved molecules against mutated KRAS-G12D oncogenic binding pockets.', 'https://github.com/ananya-m/in-silico-oncology-docking', '["AutoDock Vina","GROMACS","PyMOL","BioPython","R","Jupyter"]'::jsonb, 'Reviewed', TRUE, '92.00', 'A+', '2026-08-20T07:07:32.571Z', '2026-08-23T07:07:32.571Z', '["https://images.unsplash.com/photo-1532187863486-abf9dbad1b69?w=800&auto=format&fit=crop&q=80"]'::jsonb, 'Incubated', 'Incubated under SRMS Center for Bio-Pharma Innovation.', '250000', 'Dr. Nitin Sharma (Dean, Pharmacy)', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "tenant_rmribar"."repositories" ("repo_id", "colg_cd", "course_cd", "branch_cd", "batch_cd", "sem_cd", "student_reg_no", "student_name", "title", "description", "repo_link", "tech_stack", "status", "is_placement_eligible", "score", "grade", "submitted_at", "updated_at", "screenshots", "incubation_status", "incubation_notes", "funding_amount", "mentor_assigned", "incubated_at") VALUES (15, '1', '1', '1', '2', '5', '2025107333', 'VIKRAM CHOUDHARY', 'Decentralized Autonomous Drone Fleet for Agricultural Surveillance', 'Swarm intelligence algorithms coordinating autonomous multispectral crop health indices (NDVI) estimation and localized pesticide precision spraying.', 'https://github.com/vikram-c/agro-drone-swarm', '["ROS2","Python","OpenCV","Gazebo","TensorRT","C++"]'::jsonb, 'Reviewed', TRUE, '82.00', 'A', '2026-08-20T07:07:32.576Z', '2026-08-23T07:07:32.576Z', '["https://images.unsplash.com/photo-1508614589041-895b88991e3e?w=800&auto=format&fit=crop&q=80"]'::jsonb, 'Selected', 'Selected for agri-tech demo in State Innovation Expo.', '80000', 'Dr. Rajesh Sharma', NULL) ON CONFLICT DO NOTHING;
