INSERT INTO "tenant_srms-cet"."repositories" ("repo_id", "colg_cd", "course_cd", "branch_cd", "batch_cd", "sem_cd", "student_reg_no", "student_name", "title", "description", "repo_link", "tech_stack", "screenshots", "status", "score", "grade", "is_placement_eligible", "incubation_status", "incubation_notes", "funding_amount", "mentor_assigned", "incubated_at", "submitted_at", "updated_at") VALUES (5, '1', '2', '4', '1', '7', '2025107444', 'ANANYA MISHRA', 'Molecular Docking & In-Silico Drug Repurposing for Oncology Targets', 'Virtual screening and molecular dynamics simulations of 4,000+ FDA-approved molecules against mutated KRAS-G12D oncogenic binding pockets.', 'https://github.com/ananya-m/in-silico-oncology-docking', '["AutoDock Vina","GROMACS","PyMOL","BioPython","R","Jupyter"]'::jsonb, '["https://images.unsplash.com/photo-1532187863486-abf9dbad1b69?w=800&auto=format&fit=crop&q=80"]'::jsonb, 'Reviewed', '92.00', 'A+', TRUE, 'Incubated', 'Incubated under SRMS Center for Bio-Pharma Innovation.', '250000', 'Dr. Nitin Sharma (Dean, Pharmacy)', NULL, '2026-08-20T01:39:34.222Z', '2026-08-23T01:39:34.222Z') ON CONFLICT DO NOTHING;
