INSERT INTO "tenant_srms-cet-unnao"."repositories" ("repo_id", "colg_cd", "course_cd", "branch_cd", "batch_cd", "sem_cd", "student_reg_no", "student_name", "title", "description", "repo_link", "tech_stack", "status", "is_placement_eligible", "score", "grade", "submitted_at", "updated_at", "screenshots", "incubation_status", "incubation_notes", "funding_amount", "mentor_assigned", "incubated_at") VALUES (1, '1', '1', '1', '1', '7', '2025107990', 'AAFREEN KHAN', 'AI-Powered Diabetic Retinopathy Diagnostic Engine', 'A deep learning computer vision pipeline utilizing ResNet-50 and EfficientNet-B4 to classify high-resolution fundus images into 5 severity stages of diabetic retinopathy with 96.4% AUC accuracy.', 'https://github.com/aafreen-khan/diabetic-retinopathy-ai', '["Python","PyTorch","FastAPI","Next.js","PostgreSQL","Docker"]'::jsonb, 'Reviewed', TRUE, '94.50', 'A+', '2026-08-20T07:09:34.594Z', '2026-08-23T07:09:34.594Z', '["https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800&auto=format&fit=crop&q=80","https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=800&auto=format&fit=crop&q=80"]'::jsonb, 'Selected', 'Exceptional clinical accuracy. Fast-tracked for SRMS Incubation Center seed grant.', '150000', 'Dr. Rajesh Sharma (Head of AI Research)', NULL) ON CONFLICT DO NOTHING;
