INSERT INTO "tenant_srms-ims"."repositories" ("repo_id", "colg_cd", "course_cd", "branch_cd", "batch_cd", "sem_cd", "student_reg_no", "student_name", "title", "description", "repo_link", "tech_stack", "status", "is_placement_eligible", "score", "grade", "submitted_at", "updated_at", "screenshots", "incubation_status", "incubation_notes", "funding_amount", "mentor_assigned", "incubated_at") VALUES (3, '1', '1', '2', '1', '7', '2025107888', 'PRIYA SHARMA', 'Blockchain-Backed MedERP Electronic Health Records Protocol', 'Zero-Knowledge Proof (ZKP) cryptographic protocol securing patient medical histories, clinical prescriptions, and cross-hospital consent workflows under HIPAA & NDHM compliance.', 'https://github.com/priya-sharma/zk-ehr-blockchain', '["Solidity","Rust","Ethers.js","TypeScript","IPFS","Next.js"]'::jsonb, 'Reviewed', TRUE, '91.00', 'A+', '2026-08-20T07:09:34.045Z', '2026-08-23T07:09:34.045Z', '["https://images.unsplash.com/photo-1526374965328-7f61d4dc18c5?w=800&auto=format&fit=crop&q=80"]'::jsonb, 'Funded', 'Awarded INR 2,00,000 research & development grant by Trust Incubation Board.', '200000', 'Dr. Ankur Rastogi', NULL) ON CONFLICT DO NOTHING;
