INSERT INTO "tenant_srms-nursing-college"."repositories" ("repo_id", "colg_cd", "course_cd", "branch_cd", "batch_cd", "sem_cd", "student_reg_no", "student_name", "title", "description", "repo_link", "tech_stack", "status", "is_placement_eligible", "score", "grade", "submitted_at", "updated_at", "screenshots", "incubation_status", "incubation_notes", "funding_amount", "mentor_assigned", "incubated_at") VALUES (1, '1', '1', '1', '1', '7', '2025107990', 'AAFREEN KHAN', 'AI-Powered Diabetic Retinopathy Diagnostic Engine', 'A deep learning computer vision pipeline utilizing ResNet-50 and EfficientNet-B4 to classify high-resolution fundus images into 5 severity stages of diabetic retinopathy with 96.4% AUC accuracy.', 'https://github.com/aafreen-khan/diabetic-retinopathy-ai', '["Python","PyTorch","FastAPI","Next.js","PostgreSQL","Docker"]'::jsonb, 'Reviewed', TRUE, '94.50', 'A+', '2026-08-20T07:09:34.533Z', '2026-08-23T07:09:34.533Z', '["https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800&auto=format&fit=crop&q=80","https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=800&auto=format&fit=crop&q=80"]'::jsonb, 'Selected', 'Exceptional clinical accuracy. Fast-tracked for SRMS Incubation Center seed grant.', '150000', 'Dr. Rajesh Sharma (Head of AI Research)', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "tenant_srms-nursing-college"."repositories" ("repo_id", "colg_cd", "course_cd", "branch_cd", "batch_cd", "sem_cd", "student_reg_no", "student_name", "title", "description", "repo_link", "tech_stack", "status", "is_placement_eligible", "score", "grade", "submitted_at", "updated_at", "screenshots", "incubation_status", "incubation_notes", "funding_amount", "mentor_assigned", "incubated_at") VALUES (2, '1', '1', '1', '1', '7', '2025107666', 'JATIN PRATAP SINGH', 'Autonomous Smart Campus IoT Energy Optimization Grid', 'Distributed IoT sensors and edge computing nodes optimizing HVAC, solar array storage, and smart lighting across multi-tier campus blocks reducing peak energy drain by 28%.', 'https://github.com/jatin-pratap/smart-campus-energy-grid', '["C++","MQTT","ESP32","Node.js","InfluxDB","Grafana","React"]'::jsonb, 'Reviewed', TRUE, '88.00', 'A', '2026-08-20T07:09:34.549Z', '2026-08-23T07:09:34.549Z', '["https://images.unsplash.com/photo-1518770660439-4636190af475?w=800&auto=format&fit=crop&q=80","https://images.unsplash.com/photo-1504384308090-c894fdcc538d?w=800&auto=format&fit=crop&q=80"]'::jsonb, 'Selected', 'Approved for pilot deployment across Engineering Block A & B.', '100000', 'Prof. Ashish Kumar', NULL) ON CONFLICT DO NOTHING;
